; flags.asm -- chapter 7: what each instruction leaves in F
; generated by gen07.py
        INCLUDE "msx.inc"
        OUTPUT "flags.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld ix, RESULTS          ; A and F after each, kept for the debugger
        ld b, 1
        ld c, 0
        ld hl, h_before
        call puts
        ld c, 4
        ld hl, h_text
        call puts
        ld c, 17
        ld hl, h_after
        call puts
        ld c, 21
        ld hl, h_bits
        call puts
        ld c, 30
        ld hl, h_F
        call puts
; ADD A,1 on $7F
        ld b, 3
        ld a, $7F
        ld hl, i0
        call before
        ld de, $7F00
        push de
        pop af                  ; A = $7F, every flag clear
        add a,1
        call after
; ADD A,1 on $FF
        ld b, 5
        ld a, $FF
        ld hl, i1
        call before
        ld de, $FF00
        push de
        pop af                  ; A = $FF, every flag clear
        add a,1
        call after
; ADD A,$80 on $80
        ld b, 7
        ld a, $80
        ld hl, i2
        call before
        ld de, $8000
        push de
        pop af                  ; A = $80, every flag clear
        add a,$80
        call after
; SUB 1 on $00
        ld b, 9
        ld a, $00
        ld hl, i3
        call before
        ld de, $0000
        push de
        pop af                  ; A = $00, every flag clear
        sub 1
        call after
; CP 5 on $05
        ld b, 11
        ld a, $05
        ld hl, i4
        call before
        ld de, $0500
        push de
        pop af                  ; A = $05, every flag clear
        cp 5
        call after
; INC A on $0F
        ld b, 13
        ld a, $0F
        ld hl, i5
        call before
        ld de, $0F00
        push de
        pop af                  ; A = $0F, every flag clear
        inc a
        call after
; DEC A on $80
        ld b, 15
        ld a, $80
        ld hl, i6
        call before
        ld de, $8000
        push de
        pop af                  ; A = $80, every flag clear
        dec a
        call after
; AND $0F on $F0
        ld b, 17
        ld a, $F0
        ld hl, i7
        call before
        ld de, $F000
        push de
        pop af                  ; A = $F0, every flag clear
        and $0F
        call after
; OR 1 on $02
        ld b, 19
        ld a, $02
        ld hl, i8
        call before
        ld de, $0200
        push de
        pop af                  ; A = $02, every flag clear
        or 1
        call after
; XOR A on $55
        ld b, 21
        ld a, $55
        ld hl, i9
        call before
        ld de, $5500
        push de
        pop af                  ; A = $55, every flag clear
        xor a
        call after
; ADD A,0 on $28
        ld b, 23
        ld a, $28
        ld hl, i10
        call before
        ld de, $2800
        push de
        pop af                  ; A = $28, every flag clear
        add a,0
        call after
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; before: A = A before, HL = the instruction's text, B = the row
before: ld c, 0
        call puthex
        ld c, 4
        jp puts

; after: prints A and F as the instruction left them, and keeps them
after:  push af
        pop de                  ; D = A, E = F
        ld (ix+0), d
        ld (ix+1), e
        inc ix
        inc ix
        ld c, 17
        ld a, d
        call puthex
        ld c, 21
        ld a, e
        call fatbits            ; bit 7 on the left
        ld c, 30
        ld a, e
        jp puthex

h_before:  db "A", 0
h_text:  db "instruction", 0
h_after:  db "A", 0
h_bits:  db "SZ5H3VNC", 0
h_F:  db "F", 0
i0:     db "ADD A,1", 0
i1:     db "ADD A,1", 0
i2:     db "ADD A,$80", 0
i3:     db "SUB 1", 0
i4:     db "CP 5", 0
i5:     db "INC A", 0
i6:     db "DEC A", 0
i7:     db "AND $0F", 0
i8:     db "OR 1", 0
i9:     db "XOR A", 0
i10:     db "ADD A,0", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret

; fatbits: A = a byte, drawn as 8 boxes, bit 7 first: a filled box for 1,
;          an empty one for 0. B = row, C = column; C moves on by 8.
;          Uses A. Keeps HL.
fatbits:
        push hl
        ld l, a
        ld h, 8
.bit:   ld a, 1                 ; an empty box ...
        rl l                    ; the next bit, into the carry
        jr nc, .put
        ld a, 2                 ; ... or a filled one
.put:   call putc
        inc c
        dec h
        jr nz, .bit
        pop hl
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
